// GeamEx BLAS EX API
//
// geam_ex performs one of the matrix-matrix operations:
//
// Dij = min(alpha * (Aik + Bkj), beta * Cij)
// Dij = min(alpha * Aik, alpha * Bkj) + beta * Cij
//
// alpha and beta are scalars, and A, B, C, and D are matrices, with
// op( A ) an m by k matrix, op( B ) a k by n matrix and C and D are m by n matrices.
// C and D may point to the same matrix if their type and leading dimensions are identical.
//
// Aik refers to the element at the i-th row and k-th column of op( A ), Bkj refers to
// the element at the k-th row and j-th column of op( B ), and Cij/Dij refers to the element
// at the i-th row and j-th column of C/D.
//
// Supported types are as follows:
// - rocblas_datatype_f64_r = a_type = b_type = c_type = d_type = compute_type
// - rocblas_datatype_f32_r = a_type = b_type = c_type = d_type = compute_type
// - rocblas_datatype_f16_r = a_type = b_type = c_type = d_type = compute_type
//
// Wraps rocblas_geam_ex.
func GeamEx(handle Handle, transA Operation, transB Operation, m Int, n Int, k Int, alpha uintptr, A uintptr, aType Datatype, lda Int, B uintptr, bType Datatype, ldb Int, beta uintptr, C uintptr, cType Datatype, ldc Int, D uintptr, dType Datatype, ldd Int, computeType Datatype, geamExOp GeamExOperation) error {
	if err := checkLib(); err != nil {
		return err
	}
	return toError(fnGeamEx(handle, transA, transB, m, n, k, alpha, A, aType, lda, B, bType, ldb, beta, C, cType, ldc, D, dType, ldd, computeType, geamExOp))
}

// GemmBatchedEx BLAS EX API
//
// gemm_batched_ex performs one of the batched matrix-matrix operations:
// D_i = alpha*op(A_i)*op(B_i) + beta*C_i, for i = 1, ..., batch_count.
// where op( X ) is one of
// op( X ) = X or
// op( X ) = X**T or
// op( X ) = X**H,
// alpha and beta are scalars, and A, B, C, and D are batched pointers to matrices, with
// op( A ) an m by k by batch_count batched matrix,
// op( B ) a k by n by batch_count batched matrix and
// C and D are m by n by batch_count batched matrices.
// The batched matrices are an array of pointers to matrices.
// The number of pointers to matrices is batch_count.
// C and D may point to the same matrices if their parameters are identical.
//
// Supported types are as follows:
// - rocblas_datatype_f64_r = a_type = b_type = c_type = d_type = compute_type
// - rocblas_datatype_f32_r = a_type = b_type = c_type = d_type = compute_type
// - rocblas_datatype_f16_r = a_type = b_type = c_type = d_type = compute_type
// - rocblas_datatype_f16_r = a_type = b_type = c_type = d_type; rocblas_datatype_f32_r =
// compute_type
// - rocblas_datatype_bf16_r = a_type = b_type = c_type = d_type; rocblas_datatype_f32_r =
// compute_type
// - rocblas_datatype_i8_r = a_type = b_type; rocblas_datatype_i32_r = c_type = d_type =
// compute_type
// - rocblas_datatype_f32_c = a_type = b_type = c_type = d_type = compute_type
// - rocblas_datatype_f64_c = a_type = b_type = c_type = d_type = compute_type
//
// Wraps rocblas_gemm_batched_ex.
func GemmBatchedEx(handle Handle, transA Operation, transB Operation, m Int, n Int, k Int, alpha uintptr, a uintptr, aType Datatype, lda Int, b uintptr, bType Datatype, ldb Int, beta uintptr, c uintptr, cType Datatype, ldc Int, d uintptr, dType Datatype, ldd Int, batchCount Int, computeType Datatype, algo GemmAlgo, solutionIndex int32, flags uint32) error {
	if err := checkLib(); err != nil {
		return err
	}
	return toError(fnGemmBatchedEx(handle, transA, transB, m, n, k, alpha, a, aType, lda, b, bType, ldb, beta, c, cType, ldc, d, dType, ldd, batchCount, computeType, algo, solutionIndex, flags))
}

// GemmBatchedEx64 wraps rocblas_gemm_batched_ex_64.
func GemmBatchedEx64(handle Handle, transA Operation, transB Operation, m int64, n int64, k int64, alpha uintptr, a uintptr, aType Datatype, lda int64, b uintptr, bType Datatype, ldb int64, beta uintptr, c uintptr, cType Datatype, ldc int64, d uintptr, dType Datatype, ldd int64, batchCount int64, computeType Datatype, algo GemmAlgo, solutionIndex int32, flags uint32) error {
	if err := checkLib(); err != nil {
		return err
	}
	return toError(fnGemmBatchedEx64(handle, transA, transB, m, n, k, alpha, a, aType, lda, b, bType, ldb, beta, c, cType, ldc, d, dType, ldd, batchCount, computeType, algo, solutionIndex, flags))
}

// GemmEx BLAS EX API
//
// gemm_ex performs one of the matrix-matrix operations:
//
// D = alpha*op( A )*op( B ) + beta*C,
//
// where op( X ) is one of
//
// op( X ) = X or
// op( X ) = X**T or
// op( X ) = X**H,
//
// alpha and beta are scalars, and A, B, C, and D are matrices, with
// op( A ) an m by k matrix, op( B ) a k by n matrix and C and D are m by n matrices.
// C and D may point to the same matrix if their parameters are identical.
//
// Supported types are as follows:
// - rocblas_datatype_f64_r = a_type = b_type = c_type = d_type = compute_type
// - rocblas_datatype_f32_r = a_type = b_type = c_type = d_type = compute_type
// - rocblas_datatype_f16_r = a_type = b_type = c_type = d_type = compute_type
// - rocblas_datatype_f16_r = a_type = b_type = c_type = d_type; rocblas_datatype_f32_r =
// compute_type
// - rocblas_datatype_f16_r = a_type = b_type; rocblas_datatype_f32_r = c_type = d_type =
// compute_type
// - rocblas_datatype_bf16_r = a_type = b_type = c_type = d_type; rocblas_datatype_f32_r =
// compute_type
// - rocblas_datatype_bf16_r = a_type = b_type; rocblas_datatype_f32_r = c_type = d_type =
// compute_type
// - rocblas_datatype_i8_r = a_type = b_type; rocblas_datatype_i32_r = c_type = d_type =
// compute_type
// - rocblas_datatype_f32_c = a_type = b_type = c_type = d_type = compute_type
// - rocblas_datatype_f64_c = a_type = b_type = c_type = d_type = compute_type
//
// Although not widespread, some gemm kernels used by gemm_ex may use atomic operations.
// See Atomic Operations in the API Reference Guide for more information.
//
// Wraps rocblas_gemm_ex.
func GemmEx(handle Handle, transA Operation, transB Operation, m Int, n Int, k Int, alpha uintptr, a uintptr, aType Datatype, lda Int, b uintptr, bType Datatype, ldb Int, beta uintptr, c uintptr, cType Datatype, ldc Int, d uintptr, dType Datatype, ldd Int, computeType Datatype, algo GemmAlgo, solutionIndex int32, flags uint32) error {
	if err := checkLib(); err != nil {
		return err
	}
	return toError(fnGemmEx(handle, transA, transB, m, n, k, alpha, a, aType, lda, b, bType, ldb, beta, c, cType, ldc, d, dType, ldd, computeType, algo, solutionIndex, flags))
}

